import React, { useState, useEffect, useCallback } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Modal from '../../../components/ui/Modal/Modal';
import Button from '../../../components/ui/Button/Button';
import api from '../../../api/api';
import styles from './RedeemPrizesPage.module.css';

const RedeemPrizesPage = ({ beneficiary }) => {
  const [prizes, setPrizes] = useState([]);
  const [beneficiaryBalance, setbeneficiaryBalance] = useState(0);
  const [selectedPrize, setSelectedPrize] = useState(null);
  const [isModalOpen, setModalOpen] = useState(false);

  const fetchData = useCallback(async () => {
    if (beneficiary) {
      try {
        const [prizesRes, balanceRes] = await Promise.all([
          api.get('/prizes'),
          api.get(`/beneficiaries/${beneficiary.id}/balance`)
        ]);
        setPrizes(prizesRes.data);
        setbeneficiaryBalance(balanceRes.data.seal_balance);
      } catch (error) {
        console.error("Erro ao buscar dados:", error);
      }
    }
  }, [beneficiary]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleRedeemClick = (prize) => {
    setSelectedPrize(prize);
    setModalOpen(true);
  };

  const confirmRedemption = async () => {
    try {
      await api.post('/redemptions', {
        beneficiaryId: beneficiary.id,
        prizeId: selectedPrize.id
      });
      alert("Prémio resgatado com sucesso!");
      setModalOpen(false);
      fetchData();
    } catch (error) {
      alert(error.response?.data?.message || "Ocorreu um erro ao resgatar o prémio.");
    }
  };

  return (
    <ContentWrapper title="Resgatar Prêmios">
      <div className={styles.balanceInfo}>
        Seu Saldo: <strong>{beneficiaryBalance} selos</strong>
      </div>
      <div className={styles.grid}>
        {prizes.map(prize => {
          // CORREÇÃO: A variável 'canAfford' agora verifica se o saldo é estritamente maior que o custo.
          const canAfford = beneficiaryBalance > prize.cost;

          return (
            <div key={prize.id} className={`${styles.prizeCard} ${!canAfford ? styles.disabledCard : ''}`}>
              <h3 className={styles.prizeName}>{prize.name}</h3>
              <p className={styles.prizeCost}>{prize.cost} selos</p>
              <Button 
                onClick={() => handleRedeemClick(prize)}
                disabled={!canAfford} // Desativa o botão se o utilizador não puder pagar
              >
                {canAfford ? 'Resgatar' : 'Saldo Insuficiente'}
              </Button>
            </div>
          );
        })}
      </div>

      {/* Modal de Confirmação */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setModalOpen(false)} 
        title="Confirmar Resgate"
      >
        {selectedPrize && (
          <div>
            <p>Tem a certeza de que deseja resgatar o saldo <strong>"{selectedPrize.name}"</strong> por <strong>{selectedPrize.cost} selos</strong>?</p>
            <p>O seu novo saldo será de {beneficiaryBalance - selectedPrize.cost} selos.</p>
            <div className={styles.modalActions}>
              <Button variant="secondary" onClick={() => setModalOpen(false)}>Cancelar</Button>
              <Button onClick={confirmRedemption}>Confirmar</Button>
            </div>
          </div>
        )}
      </Modal>
    </ContentWrapper>
  );
};

export default RedeemPrizesPage;
